28	
29	    private final ObjectMapper mapper = new ObjectMapper();
30	
31	    private HttpHeaders headers(String actor, String role, String requestId) {
32	        HttpHeaders h = new HttpHeaders();
33	        if (actor != null) {
34	            h.set("X-Actor-Id", actor);
35	        }
36	        if (role != null) {
37	            h.set("X-Role", role);
38	        }
