160	                headers("c1", "ADMIN", "idem-key-6"), "{\"blockCount\":2}");
161	        assertEquals(401, badRole.getStatusCode().value());
162	
163	        // 先用合法协调员成功占用 requestId
164	        assertEquals(201, post("/api/experiments/IDEM-6",
165	                headers("c1", "COORDINATOR", "idem-key-6"), "{\"blockCount\":2}")
166	                .getStatusCode().value());
167	
168	        // 权限不足（REVIEWER 做协调员操作）必须 403，而非按幂等回放/409——权限先于幂等
169	        ResponseEntity<String> reviewerReplay = post("/api/experiments/IDEM-6",
170	                headers("c1", "REVIEWER", "idem-key-6"), "{\"blockCount\":2}");
171	        assertEquals(403, reviewerReplay.getStatusCode().value());
172	
173	        // 缺身份头同样 401，而不是回放
174	        assertEquals(401, post("/api/experiments/IDEM-6",
175	                headers(null, null, "idem-key-6"), "{\"blockCount\":2}")
176	                .getStatusCode().value());
177	    }
178	
179	    @Test
180	    void allocationWithdrawCloseWrites_areIdempotent_replayOriginalResult() {
181	        assertEquals(201, post("/api/experiments/IDEM-10",
182	                headers("c1", "COORDINATOR", "idem-10-create"), "{\"blockCount\":2}")
183	                .getStatusCode().value());
184	
185	        // 登记：同键重放原 201（而非重复登记 409）
186	        ResponseEntity<String> alloc1 = post(
187	                "/api/experiments/IDEM-10/participants/P1/allocations",
188	                headers("c1", "COORDINATOR", "idem-10-alloc"), null);
189	        assertEquals(201, alloc1.getStatusCode().value());
190	        ResponseEntity<String> allocReplay = post(
191	                "/api/experiments/IDEM-10/participants/P1/allocations",
192	                headers("c1", "COORDINATOR", "idem-10-alloc"), null);
193	        assertEquals(201, allocReplay.getStatusCode().value());
194	        assertEquals(alloc1.getBody(), allocReplay.getBody());
195	        assertEquals(1, jdbc.queryForObject(
196	                "SELECT COUNT(*) FROM allocation WHERE experiment_id = 'IDEM-10'", Integer.class));
197	
198	        // 退组：同键重放原 200 与 WITHDRAWN（而非重复退组 409）
199	        ResponseEntity<String> withdraw1 = post(
200	                "/api/experiments/IDEM-10/participants/P1/withdrawal",
201	                headers("c1", "COORDINATOR", "idem-10-withdraw"), null);
202	        assertEquals(200, withdraw1.getStatusCode().value());
203	        ResponseEntity<String> withdrawReplay = post(
204	                "/api/experiments/IDEM-10/participants/P1/withdrawal",
205	                headers("c1", "COORDINATOR", "idem-10-withdraw"), null);
206	        assertEquals(200, withdrawReplay.getStatusCode().value());
207	        assertEquals(withdraw1.getBody(), withdrawReplay.getBody());
208	
209	        // 关闭：同键重放原 200 与 CLOSED（而非重复关闭 409）
210	        ResponseEntity<String> close1 = post("/api/experiments/IDEM-10/close",
211	                headers("c1", "COORDINATOR", "idem-10-close"), null);
212	        assertEquals(200, close1.getStatusCode().value());
213	        ResponseEntity<String> closeReplay = post("/api/experiments/IDEM-10/close",
214	                headers("c1", "COORDINATOR", "idem-10-close"), null);
215	        assertEquals(200, closeReplay.getStatusCode().value());
216	        assertEquals(close1.getBody(), closeReplay.getBody());
217	    }
218	
219	    @Test
220	    void reviewerCannotCreateOrAllocate_coordinatorCannotApprove() {
221	        assertEquals(201, post("/api/experiments/IDEM-7",
222	                headers("c1", "COORDINATOR", "idem-key-7"), "{\"blockCount\":2}")
223	                .getStatusCode().value());
224	
225	        assertEquals(403, post("/api/experiments/IDEM-8",
226	                headers("r1", "REVIEWER", "idem-key-8"), "{\"blockCount\":2}")
227	                .getStatusCode().value());
228	        assertEquals(403, post(
